import re

POOL = re.compile(r"^\s*Ltm::Pool: (?P<pool>\S+)\s*$")
MEMBER = re.compile(r"^\s*Ltm::Pool Member: (?P<member>\S+)\s*$")
KV = re.compile(r"^\s*(?P<key>[A-Za-z][A-Za-z ]*?)\s*: (?P<value>\S.*?)\s*$")
TRAFFIC = re.compile(r"^\s*Traffic\s+(?P<cols>\S.*?)\s*$")
ROW = re.compile(r"^\s+(?P<counter>[A-Za-z][A-Za-z ]*?)\s{2,}(?P<vals>\S.*?)\s*$")
RULE = re.compile(r"^\s*-{5,}\s*$")
PROMPT = re.compile(r"\(tmos\)# ")
STATUS = re.compile(r"^\s*Status\s*$")


def _widen(block, lead):
    cols = list(lead)
    for r in block["records"]:
        cols += [k for k in r if k not in cols]
    block["records"] = [{k: r.get(k, "") for k in cols} for r in block["records"]]


def parse(lines):
    status = {"name": "status", "kind": "table", "lines": [], "records": []}
    traffic = {"name": "traffic", "kind": "table", "lines": [], "records": []}
    skip = []
    pool = member = ""
    cols, cur, mode = [], None, ""
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        if RULE.match(ln) or PROMPT.search(ln):
            skip.append(i)
            continue
        m = POOL.match(ln)
        if m:
            pool, member = m.group("pool"), ""
            skip.append(i)
            continue
        m = MEMBER.match(ln)
        if m:
            member = m.group("member")
            skip.append(i)
            continue
        if STATUS.match(ln):
            cur = {"Pool": pool, "Member": member}
            status["records"].append(cur)
            status["lines"].append(i)
            mode = "status"
            continue
        m = TRAFFIC.match(ln)
        if m:
            cols = re.split(r"\s{2,}", m.group("cols"))
            traffic["lines"].append(i)
            mode = "traffic"
            continue
        if mode == "status":
            m = KV.match(ln)
            if m and cur is not None:
                cur[m.group("key")] = m.group("value")
                status["lines"].append(i)
                continue
        if mode == "traffic":
            m = ROW.match(ln)
            if m:
                vals = m.group("vals").split()
                rec = {"Pool": pool, "Member": member, "Traffic": m.group("counter")}
                for k, v in zip(cols, vals + [""] * (len(cols) - len(vals))):
                    rec[k] = v
                traffic["records"].append(rec)
                traffic["lines"].append(i)
    _widen(status, ["Pool", "Member"])
    _widen(traffic, ["Pool", "Member", "Traffic"])
    return {"blocks": [status, traffic], "skip": skip}
